import {questions,validate,diagnose,plan} from './model.js';
import {riskPanel,bindRisk} from './risk-ui.js';
import {distributionPanel,candidatesPanel} from './strategy-extras.js';
import {bindDrafts,updateDraft,clearDrafts,exportDrafts} from './drafts.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({profile:{},rules:{months:3,debtRatio:30},messages:[],demo:false});let state=initial();try{const saved=JSON.parse(localStorage.getItem('brujula-v1'));if(saved&&saved.profile&&saved.rules&&Array.isArray(saved.messages))state=saved;}catch{}let view='inicio',market=[],search='',period='1',sort='desc';
const money=n=>n===null||n===undefined?'—':new Intl.NumberFormat('es-MX',{style:'currency',currency:state.profile.currency||'MXN',maximumFractionDigits:0}).format(n);const pct=n=>Number.isFinite(n)?`${n>0?'+':''}${n.toFixed(1)}%`:'—';const index=()=>questions.findIndex(q=>state.profile[q.key]===undefined);const completed=()=>questions.filter(q=>state.profile[q.key]!==undefined).length;const save=()=>{try{localStorage.setItem('brujula-v1',JSON.stringify(state));}catch{toast('No se pudo guardar en este navegador. Puedes descargar tu resumen.');}};function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function go(v){view=v;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadcrumb').textContent={inicio:'Mi panorama',diagnostico:'Diagnóstico',estrategia:'Mi estrategia',mercado:'Explorar stockEX'}[v];render();window.scrollTo(0,0);}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('inicio');};
const demoNotice=()=>state.demo?'<div class="demo-label">Modo ejemplo · Cifras ficticias para explorar la experiencia</div>':'';
function intro(title,sub){return `${demoNotice()}<div class="intro"><div><div class="eyebrow">TU DINERO, CON DIRECCIÓN</div><h1>${title}</h1><p>${sub}</p></div><span class="pill">✧ &nbsp; Un paso a la vez</span></div>`;}
function stats(d){return `<div class="stats"><div class="stat"><div class="stat-label">Disponible cada mes <span>↗</span></div><strong>${d?money(d.free):'—'}</strong><small>${d?'Ingreso menos gastos y pagos de deudas':'Lo calcularemos con tus respuestas'}</small></div><div class="stat"><div class="stat-label">Reserva de emergencia <span>◇</span></div><strong>${d?d.coverage===null?'Sin base de gastos':`${d.coverage.toFixed(1)} meses`:'—'}</strong><small>${d?`Referencia configurable: ${state.rules.months} meses`:'Primero, conocer tu tranquilidad financiera'}</small></div><div class="stat"><div class="stat-label">Capital adicional declarado <span>◎</span></div><strong>${d?money(state.profile.capital):'—'}</strong><small>Se evalúa por separado de tu fondo de emergencia</small></div></div>`;}
function chat(full=false){const q=questions[index()];return `<section class="card chat-card ${full?'full-chat':''}"><div class="chat-header"><div class="assistant-icon">✳</div><div><strong>Tu guía financiera</strong><small>Diagnóstico conversacional</small></div><span class="pill purple">Guía por reglas</span></div><div class="messages" id="messages" role="log" aria-live="polite">${state.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}<div class="message"><div class="message-label">BRÚJULA</div>${esc(q?q.text:'Ya tenemos tu primera fotografía financiera. Puedes revisar el diagnóstico, ajustar tus respuestas o explorar tu estrategia.')}</div></div><div class="chat-compose">${q?.chips?`<div class="suggestions">${q.chips.map(s=>`<button class="chip" data-answer="${esc(s)}">${esc(s)}</button>`).join('')}</div>`:''}${q?`<form id="chat-form"><div class="input-row"><input id="answer" aria-label="${esc(q.label)}" placeholder="${q.type==='money'?'Escribe el monto en '+esc(state.profile.currency):'Escribe tu respuesta…'}" autocomplete="off" maxlength="500" ${q.type==='money'?'inputmode="decimal"':''}><button class="send" aria-label="Enviar respuesta">↑</button></div></form>`:'<button class="primary" data-go="diagnostico">Ver mi diagnóstico <span>↗</span></button>'}<small>Respuestas guardadas en este navegador. Puedes borrarlas cuando quieras.</small></div></section>`;}
function table(rows,compact=false){return `<div class="table-scroll"><table><thead><tr><th>Activo</th><th>Último cierre del archivo</th><th>1 mes</th><th>6 meses</th><th>12 meses</th>${compact?'':'<th>Fuente</th>'}<th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="ticker"><span class="ticker-icon">${esc(r.ticker.slice(0,2))}</span>${esc(r.ticker)}</div></td><td>${r.price===null?'—':new Intl.NumberFormat('es-MX',{style:'currency',currency:'USD'}).format(r.price)} <small class="muted">USD</small></td>${['1','6','12'].map(k=>`<td class="${r[k]>=0?'up':'down'}">${pct(r[k])}</td>`).join('')}${compact?'':'<td class="muted">CSV · 29 oct 2026</td>'}<td><button class="detail-link" data-ticker="${esc(r.ticker)}">Ver análisis ↗</button></td></tr>`).join('')||'<tr><td colspan="7">No hay activos que coincidan.</td></tr>'}</tbody></table></div>`;}
function home(d){return intro('Tu próximo paso empieza aquí.','Entiende dónde estás. Decide hacia dónde quieres ir.')+`<div class="overview"><section class="hero"><div class="eyebrow">CLARIDAD ANTES DE DECIDIR</div><h2>${d?'Tu estrategia empieza<br>con tu realidad.':'Conoce tus finanzas.<br>Traza tu propio camino.'}</h2><p>${d?esc(d.status):'Una conversación para entender tu situación y convertir tus objetivos en un plan personal.'}</p><button class="primary" data-go="${d?'estrategia':'diagnostico'}">${d?'Explorar mi estrategia':completed()?'Continuar mi diagnóstico':'Empezar mi diagnóstico'} <span>↗</span></button><div class="compass" aria-hidden="true"><span>N</span></div></section><section class="progress-card"><div class="progress-top"><div><div class="eyebrow">TU PUNTO DE PARTIDA</div><h3>Vamos a conocerte</h3></div><div class="progress-ring" style="--progress:${completed()/questions.length*100}%"><strong>${Math.round(completed()/questions.length*100)}<small>%</small></strong></div></div><p>${completed()} de ${questions.length} respuestas para construir tu primera fotografía financiera.</p><div class="small-progress">${questions.map((q,i)=>`<span class="${i<completed()?'done':''}"></span>`).join('')}</div></section></div>`+stats(d)+`<div class="work-grid"><div><div class="section-head"><h2>Hablemos de tus objetivos</h2><span class="muted" style="font-size:10px">A tu ritmo</span></div>${chat()}</div><div><div class="section-head"><h2>Un camino con sentido</h2></div><section class="card"><div class="steps">${[['01','Conoce tu punto de partida','Ingresos, gastos, deudas y ahorro. Toda tu situación en contexto.'],['02','Construye tu estrategia','Prioridades y próximos pasos según tus objetivos.'],['03','Explora con información','Consulta oportunidades de stockEX y entiende sus señales.']].map(s=>`<div class="step"><span class="step-num">${s[0]}</span><div><h3>${s[1]}</h3><p>${s[2]}</p></div></div>`).join('')}</div><div class="side-foot">✧ &nbsp; Una oportunidad cobra sentido cuando encaja con tu vida.</div></section></div></div><section class="market-teaser"><div class="section-head"><div class="market-title"><h2>Una mirada al mercado</h2><small>stockEX · archivo del 29 oct 2026</small></div><button class="text-button" data-go="mercado">Explorar activos ↗</button></div><div class="card">${table(market.filter(r=>['PTON','NET','FSLR'].includes(r.ticker)),true)}</div></section>`;}
function diagnosisView(d){return intro('Tu fotografía financiera.','Las cifras cuentan una historia. Vamos a entender la tuya.')+(!d?`<div class="notice">Paso ${completed()+1} de ${questions.length}. Puedes corregir respuestas previas más abajo.</div>${chat(true)}`:`<div class="notice">${esc(d.status)}. Este diagnóstico usa tus respuestas y referencias editables. ${d.reasons.length?esc(d.reasons.join(' ')):'Aún falta evaluar cada instrumento, sus costos y su compatibilidad con tus objetivos.'}</div>${stats(d)}<div class="diagnostic-grid"><section class="card"><div class="eyebrow">FLUJO MENSUAL · ${esc(state.profile.currency)}</div><h2>${money(d.free)} disponibles</h2><p class="muted">${money(state.profile.income)} de ingreso − ${money(state.profile.expenses)} de gastos − ${money(state.profile.debtPayment)} de pagos de deudas.</p><div class="meter"><span style="width:${state.profile.income>0?Math.min(100,Math.max(0,d.free/state.profile.income*100)):0}%"></span></div><small class="muted">Excedente de flujo; no implica una asignación automática a inversiones.</small></section><section class="card"><div class="eyebrow">RESERVA DISPONIBLE</div><h2>${money(state.profile.savings)} ahorrados</h2><p class="muted">Objetivo según tu referencia: ${money(d.target)}. Diferencia pendiente: ${money(d.gap)}.</p><div class="meter"><span style="width:${d.target?Math.min(100,state.profile.savings/d.target*100):0}%"></span></div><small class="muted">Base: gastos esenciales + pagos mensuales de deudas.</small></section><section class="card"><div class="eyebrow">COMPROMISOS</div><h2>${money(state.profile.debt)} de deuda</h2><p class="muted">${d.ratio===null?'No se calcula proporción sin ingreso.':`${d.ratio.toFixed(1)}% de tu ingreso se destina a pagos de deudas.`}</p><small class="muted">${d.reviewDebt?'Supera la referencia de revisión configurada. ':''}Para priorizar faltan tasas y condiciones de cada deuda.</small></section><section class="card"><div class="eyebrow">TU PERFIL DECLARADO</div><h2>${esc(state.profile.horizon)}</h2><p class="muted">${esc(state.profile.experience)} · Caída tolerable: ${esc(state.profile.tolerance.toLowerCase())}.</p><small class="muted">Objetivo: ${esc(state.profile.goal)}</small></section></div><div style="margin-top:20px"><button class="primary" data-go="estrategia">Ver mi estrategia ↗</button></div>`)+`<section class="card" style="margin-top:24px"><h2>Mis respuestas</h2><p class="muted">Edita un dato y guarda para recalcular tu diagnóstico.</p><form id="profile-form"><div class="profile-fields">${questions.filter(q=>state.profile[q.key]!==undefined).map(q=>`<label>${q.label}${q.type==='choice'||q.type==='currency'?`<select name="${q.key}" style="width:100%;padding:10px;margin-top:7px;border:1px solid var(--border);border-radius:7px">${(q.chips).map(c=>`<option ${state.profile[q.key]===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:`<input name="${q.key}" value="${esc(state.profile[q.key])}" ${q.type==='money'?'inputmode="decimal"':''} required>`}</label>`).join('')}</div>${completed()?'<button class="secondary" style="margin-top:18px">Guardar respuestas</button>':'<p class="muted">Tus respuestas aparecerán aquí.</p>'}</form></section><div class="reset-row"><button class="text-button" id="demo">Cargar un ejemplo ficticio</button><button class="text-button danger" id="reset">Borrar mis datos y empezar de nuevo</button></div>`;}
function strategyView(d){return intro('Una estrategia que parte de ti.','Prioridades claras, decisiones explicadas y espacio para ajustar el rumbo.')+(!d?`<section class="card empty"><div class="assistant-icon" style="margin:0 auto 20px">✳</div><h2>Primero, tu punto de partida</h2><p>Completa la conversación para construir un plan con tus cifras y tus objetivos.</p><button class="primary" data-go="diagnostico">Continuar diagnóstico ↗</button></section>`:`<div class="notice">${esc(d.status)}. Las acciones siguientes son una guía inicial basada en reglas. Las referencias son supuestos de esta versión, ajustables a tu contexto.</div><section class="card"><div class="eyebrow">TU PLAN PERSONAL · ${esc(state.profile.currency)}</div><h2>${esc(state.profile.goal)}</h2>${plan(state.profile,d,state.rules).map(([t,p],i)=>`<div class="action"><span class="step-num">0${i+1}</span><div><h3>${esc(t)}</h3><p>${esc(p)}</p></div></div>`).join('')}</section>`)+`<section class="card" style="margin-top:20px"><h2>Referencias del diagnóstico</h2><p class="muted">Supuestos iniciales de la app. No son umbrales universales ni una certificación para invertir.</p><form id="rules-form"><div class="settings"><label>Reserva en meses<input name="months" type="number" min="1" max="24" step="1" value="${state.rules.months}" required></label><label>Revisar pagos de deuda sobre ingreso (%)<input name="debtRatio" type="number" min="1" max="100" value="${state.rules.debtRatio}" required></label><button class="secondary">Actualizar referencias</button></div></form></section>`;}
function marketView(){let rows=market.filter(r=>r.ticker.includes(search.toUpperCase())).sort((a,b)=>((a[period]??-Infinity)-(b[period]??-Infinity))*(sort==='desc'?-1:1));return intro('El mercado, con contexto.','Explora el análisis de stockEX. Entiende los datos antes de dar el siguiente paso.')+`<div class="notice"><b>Fotografía histórica · archivos del 29 de octubre de 2026.</b> No son cotizaciones en tiempo real. Se conserva el universo de los CSV, sin asumir que todos los activos pertenecen al S&P 500. Los rendimientos pasados no son proyecciones.</div><div class="filter-bar"><input id="search" aria-label="Buscar símbolo" placeholder="Buscar símbolo, por ejemplo PTON" value="${esc(search)}"><select id="period" aria-label="Periodo para ordenar"><option value="1" ${period==='1'?'selected':''}>Rendimiento a 1 mes</option><option value="6" ${period==='6'?'selected':''}>Rendimiento a 6 meses</option><option value="12" ${period==='12'?'selected':''}>Rendimiento a 12 meses</option></select><select id="sort" aria-label="Orden"><option value="desc" ${sort==='desc'?'selected':''}>Mayor a menor</option><option value="asc" ${sort==='asc'?'selected':''}>Menor a mayor</option></select></div><div class="section-head"><h2>${rows.length} activos del archivo</h2><span class="pill purple">stockEX · datos importados</span></div><section class="card" style="padding:0 16px">${table(rows)}</section><p class="chart-note" style="margin-top:16px">No se publican niveles operativos automáticos hasta validar la fórmula RRR, la dirección de la operación y la vigencia de las fuentes.</p>`;}
function render(){const d=diagnose(state.profile,state.rules);$('#main').innerHTML=view==='inicio'?home(d):view==='diagnostico'?diagnosisView(d):view==='estrategia'?strategyView(d):marketView();if(view==='estrategia'){$('#main .intro').insertAdjacentHTML('afterend',candidatesPanel(market,state,d)+(d?distributionPanel(state):''));}if(view==='estrategia'&&d){if(state.risk?.currency!==state.profile.currency)state.risk=undefined;$('#candidate-panel').insertAdjacentHTML('afterend',riskPanel(state,d));bindRisk(state,r=>{state.risk=r;save();render();document.querySelector('#risk-panel').scrollIntoView({block:'start'});toast('Límites y simulación guardados');});}bind();bindDrafts();document.querySelectorAll('[data-analyze]').forEach(button=>button.onclick=()=>{if(!d){go('diagnostico');return;}updateDraft('risk-form',{symbol:button.dataset.analyze,entry:'',stop:'',cost:''});render();document.querySelector('#risk-panel').scrollIntoView({block:'start',behavior:'smooth'});document.querySelector('#risk-form [name=entry]')?.focus();});const log=$('#messages');if(log)log.scrollTop=log.scrollHeight;}
function submit(raw){const q=questions[index()];if(!q||!raw.trim())return;const result=validate(q,raw,state.profile);if(result.error){state.messages.push({role:'assistant',text:result.error});render();return;}state.messages.push({role:'assistant',text:q.text},{role:'user',text:raw.trim()});state.profile[q.key]=result.value;save();render();$('#answer')?.focus();}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>submit(b.dataset.answer));if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();submit($('#answer').value);};if($('#rules-form'))$('#rules-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),months=Number(f.get('months')),debtRatio=Number(f.get('debtRatio'));if(!Number.isInteger(months)||months<1||months>24||debtRatio<1||debtRatio>100)return;state.rules={months,debtRatio};save();render();toast('Referencias actualizadas');};if($('#profile-form'))$('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p={...state.profile};for(const q of questions){if(!f.has(q.key))continue;const v=validate(q,String(f.get(q.key)),p);if(v.error){toast(q.label+': '+v.error);return;}p[q.key]=v.value;}if(p.essentials>p.expenses){toast('Revisa los gastos esenciales y totales.');return;}state.profile=p;state.messages=[];save();render();toast('Diagnóstico actualizado');};if($('#demo'))$('#demo').onclick=()=>{if(completed()&&!confirm('El ejemplo reemplazará tus respuestas guardadas. ¿Continuar?'))return;clearDrafts();state={...initial(),demo:true,profile:{goal:'Construir patrimonio a largo plazo',currency:'MXN',income:35000,expenses:20000,essentials:15000,debtPayment:3000,debt:45000,savings:30000,capital:10000,horizon:'Más de 3 años',experience:'Estoy empezando',tolerance:'Hasta 5%'}};save();render();};if($('#reset'))$('#reset').onclick=()=>{if(confirm('¿Borrar las respuestas guardadas en este navegador?')){state=initial();try{localStorage.removeItem('brujula-v1');clearDrafts();}catch{}render();}};document.querySelectorAll('[data-ticker]').forEach(b=>b.onclick=()=>detail(b.dataset.ticker));if($('#search'))$('#search').oninput=e=>{search=e.target.value;const start=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start);};if($('#period'))$('#period').onchange=e=>{period=e.target.value;render();};if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render();};}
function detail(ticker){const r=market.find(x=>x.ticker===ticker);if(!r)return;const d=diagnose(state.profile,state.rules);$('#detail-content').innerHTML=`<div class="eyebrow">STOCKEX · ARCHIVO HISTÓRICO</div><h1>${esc(ticker)}</h1><p>Rendimiento entre el primer y último cierre de cada ventana del CSV. La fecha del archivo es 29 oct 2026; los CSV no incluyen las fechas de cada observación.</p><div class="bar-chart">${['1','6','12'].map(k=>`<div class="bar-column"><b class="${r[k]>=0?'up':'down'}">${pct(r[k])}</b><div class="bar ${r[k]<0?'negative':''}" style="height:${Number.isFinite(r[k])?Math.max(3,Math.abs(r[k])/Math.max(1,...['1','6','12'].map(j=>Math.abs(r[j]??0)))*95):0}px"></div><span>${k} ${k==='1'?'mes':'meses'}</span></div>`).join('')}</div><p class="chart-note">Barras de magnitud; el signo y el color indican ganancia o pérdida.</p><h3>Cómo encaja con tu situación</h3><p>${d?esc(d.status)+'. '+(d.reasons.length?'Completa las prioridades de tu estrategia antes de definir una asignación.':'Se requiere analizar el instrumento, liquidez, diversificación y costos antes de proponer una asignación.'):'Completa tu diagnóstico para aportar contexto personal a este análisis.'}</p><div class="notice">Estado: pendiente de evaluación individual. Objetivo de compra, venta, stop y calls/puts no están incluidos en estos CSV. La tabla manual requiere conciliación antes de utilizarse.</div><p>Movimiento absoluto medio del archivo a 1 mes: ${r.movement===null?'no disponible':r.movement.toFixed(2)+'%'}. Es una métrica propia de stockEX; no equivale a volatilidad anualizada.</p>`;$('#detail').showModal();}
$('#detail .close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close();};$('#export').onclick=()=>{const d=diagnose(state.profile,state.rules),payload={app:'Brújula v1',exportedAt:new Date().toISOString(),drafts:exportDrafts(),demo:state.demo,profile:state.profile,references:state.rules,risk:state.risk?.currency===state.profile.currency?state.risk:null,diagnosis:d,plan:d?plan(state.profile,d,state.rules):[],marketSource:'CSV 26_10_29 · histórico, no cotizaciones actuales'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mi-estrategia-brujula.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Resumen descargado');};
render();fetch('market.json').then(r=>{if(!r.ok)throw new Error('market');return r.json();}).then(rows=>{market=rows;render();}).catch(()=>toast('No se pudieron cargar los archivos de mercado. El diagnóstico sigue disponible.'));

